<script lang="ts">
 import {onDestroy} from 'svelte';import {doc,onSnapshot} from 'firebase/firestore';import {db} from '$lib/firebase';import {api} from '$lib/api/api';import {catalogApi} from '$lib/api/catalog';import type {Character} from '$lib/types';import {normalizeBuild} from '$lib/rules/characterBuilder';import {resourcePools,resourceSuggestions,type ResourcePool} from '$lib/rules/tablePlay';
 export let character:Character;let pools:ResourcePool[]=[];let loading=true;let error='';let busy=false;let editing:ResourcePool|null=null;let suggestions:Omit<ResourcePool,'id'>[]=[];let key='';let unsubscribe:()=>void;
 $: if(`${character.id}:${character.instanceId||character.createdAt}`!==key){key=`${character.id}:${character.instanceId||character.createdAt}`;listen();}
 function listen(){unsubscribe?.();pools=[];loading=true;unsubscribe=onSnapshot(doc(db,'character_resources',character.id),snapshot=>{loading=false;const data=snapshot.data();pools=data?.instanceId===(character.instanceId||'')?resourcePools(data.poolsJson):[];},cause=>{loading=false;error=cause.message;});}
 async function mutate(change:Parameters<typeof api.changeResource>[1]){if(busy)return;busy=true;error='';try{await api.changeResource(character.id,change);editing=null;}catch(cause){error=cause instanceof Error?cause.message:'No se pudo guardar.';}finally{busy=false;}}
 async function presets(){error='';try{const build=normalizeBuild(character.build);const option=build.class.key?await catalogApi.getOption(build.class.key):null;suggestions=resourceSuggestions(build,option,character.level);}catch{error='No se pudieron consultar los recursos de la clase.';}}
 function fresh(pool?:Omit<ResourcePool,'id'>){editing={id:api.newResourceId(),name:pool?.name||'',max:pool?.max||1,current:pool?.max||1,recovery:pool?.recovery||'manual'};}
 onDestroy(()=>unsubscribe?.());
</script>
<section class="space-y-2 text-neutral">
 <div class="flex items-center gap-2"><h3 class="font-medieval font-bold flex-1">Recursos</h3><button class="btn btn-xs" disabled={loading} on:click={()=>fresh()}>+ Recurso</button></div>
 {#if error}<p role="alert" class="text-error text-sm">{error}</p>{/if}
 {#if loading}<p class="text-sm" role="status">Cargando recursos…</p>{:else if !pools.length}<p class="text-sm">Todavía no tenés recursos configurados.</p>{/if}
 {#each pools as pool}<div class="border border-primary/30 rounded p-2"><div class="flex items-center gap-2"><span class="text-sm font-semibold flex-1 min-w-0 break-words">{pool.name}</span><button class="btn btn-xs" aria-label={`Restar ${pool.name}`} disabled={busy||pool.current===0} on:click={()=>mutate({kind:'adjust',id:pool.id,delta:-1})}>−</button><strong class="text-sm whitespace-nowrap">{pool.current}/{pool.max}</strong><button class="btn btn-xs" aria-label={`Sumar ${pool.name}`} disabled={busy||pool.current>=pool.max} on:click={()=>mutate({kind:'adjust',id:pool.id,delta:1})}>+</button></div><div class="flex justify-between text-xs mt-1"><span>Recupera: {pool.recovery==='short'?'descanso corto o largo':pool.recovery==='long'?'descanso largo':'manual'}</span><button class="link" on:click={()=>editing={...pool}}>Configurar</button></div></div>{/each}
 <details class="border border-primary/20 p-2 rounded"><summary class="cursor-pointer text-sm" on:click={presets}>Sugerencias de la ficha</summary><p class="text-xs my-2">Revisá el máximo y la recuperación antes de añadir cada contador. Los valores existentes se conservan.</p>{#each suggestions as pool}<button class="btn btn-xs m-1" on:click={()=>fresh(pool)}>{pool.name} ({pool.max})</button>{/each}{#if !suggestions.length}<p class="text-xs">Podés crear recursos personalizados o configurar los espacios máximos en la ficha.</p>{/if}</details>
 {#if editing}<div class="border-2 border-secondary rounded p-3 space-y-2"><label class="block text-sm">Nombre<input class="input input-bordered input-sm w-full" bind:value={editing.name} maxlength="100"/></label><label class="block text-sm">Máximo<input class="input input-bordered input-sm w-full" type="number" min="0" max="9999" bind:value={editing.max}/></label><label class="block text-sm">Recuperación<select class="select select-bordered select-sm w-full" bind:value={editing.recovery}><option value="manual">Manual</option><option value="short">Descanso corto o largo</option><option value="long">Descanso largo</option></select></label><div class="flex flex-wrap gap-2"><button class="btn btn-sm" disabled={busy||!editing.name.trim()} on:click={()=>{if(editing)mutate({kind:'save',pool:{...editing,current:Math.min(editing.current,editing.max)}});}}>Guardar recurso</button><button class="btn btn-sm" disabled={busy} on:click={()=>editing=null}>Cancelar</button>{#if pools.some(p=>p.id===editing?.id)}<button class="btn btn-sm btn-error" disabled={busy} on:click={()=>{if(editing&&confirm('¿Quitar este contador?'))mutate({kind:'remove',id:editing.id});}}>Quitar</button>{/if}</div></div>{/if}
</section>
<style>.input,.select{color:#f7ecd8;background:#2d241c;}</style>
